  `school_email` varchar(120) DEFAULT NULL,
  `school_website` varchar(255) DEFAULT NULL,
  `instagram_url` varchar(255) DEFAULT NULL,
  `school_youtube` varchar(255) DEFAULT NULL,
  `tiktok_url` varchar(255) DEFAULT NULL,
  `school_logo` varchar(500) DEFAULT NULL,
  `favicon` varchar(500) DEFAULT NULL,
  `theme_preset` varchar(50) NOT NULL DEFAULT 'purple',
  `theme_primary` varchar(20) DEFAULT NULL,
  `theme_secondary` varchar(20) DEFAULT NULL,
