  `google_drive_folder_id` varchar(255) DEFAULT NULL,
  `google_drive_service_account_json` varchar(255) DEFAULT NULL,
  `google_drive_auto_upload` tinyint(1) NOT NULL DEFAULT 0,
  `google_drive_keep_local` tinyint(1) NOT NULL DEFAULT 1,
