  `status` enum('upcoming','active','archived') NOT NULL DEFAULT 'upcoming',
  `reg_number_pattern` varchar(50) NOT NULL DEFAULT 'SPMB-{YEAR}-{NUMBER:4}' COMMENT 'Pattern untuk generate nomor registrasi',
  `reg_number_current` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'Counter nomor registrasi saat ini',
  `total_pendaftar` int(10) unsigned NOT NULL DEFAULT 0,
  `total_diterima` int(10) unsigned NOT NULL DEFAULT 0,
  `total_belum_daftar_ulang` int(10) unsigned NOT NULL DEFAULT 0,
  `started_at` date DEFAULT NULL COMMENT 'Tanggal mulai pendaftaran',
  `closed_at` date DEFAULT NULL COMMENT 'Tanggal tutup pendaftaran',
  `created_by` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `tahun_ajaran_tahun_unique` (`tahun`),
  KEY `tahun_ajaran_status_index` (`status`),
  KEY `tahun_ajaran_tahun_index` (`tahun`),
  KEY `tahun_ajaran_created_by_index` (`created_by`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
