DROP TABLE IF EXISTS `whatsapp_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `whatsapp_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `phone` varchar(20) NOT NULL,
  `phone_normalized` varchar(20) DEFAULT NULL,
  `message` text NOT NULL,
  `status` enum('pending','sent','failed') NOT NULL DEFAULT 'pending',
  `tahun_ajaran` varchar(9) NOT NULL DEFAULT '2026/2027' COMMENT 'Format: YYYY/YYYY, contoh: 2027/2028',
  `type` varchar(50) NOT NULL DEFAULT 'manual',
  `pendaftar_id` bigint(20) unsigned DEFAULT NULL,
  `external_batch_id` bigint(20) unsigned DEFAULT NULL,
  `template_id` bigint(20) unsigned DEFAULT NULL,
  `sent_by` bigint(20) unsigned DEFAULT NULL,
  `error_message` text DEFAULT NULL,
  `sent_at` timestamp NULL DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `whatsapp_logs_pendaftar_id_index` (`pendaftar_id`),
  KEY `whatsapp_logs_template_id_index` (`template_id`),
  KEY `whatsapp_logs_sent_by_index` (`sent_by`),
  KEY `whatsapp_logs_status_index` (`status`),
  KEY `whatsapp_logs_type_index` (`type`),
  KEY `whatsapp_logs_sent_at_index` (`sent_at`),
  KEY `whatsapp_logs_created_at_index` (`created_at`),
  KEY `whatsapp_logs_phone_index` (`phone`),
  KEY `whatsapp_logs_external_batch_id_index` (`external_batch_id`),
  KEY `whatsapp_logs_phone_normalized_index` (`phone_normalized`),
  KEY `whatsapp_logs_tahun_ajaran_index` (`tahun_ajaran`)
) ENGINE=InnoDB AUTO_INCREMENT=130 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
