INSERT INTO `whatsapp_templates` VALUES (1,'welcome_registration','Pesan Selamat Datang - Pendaftaran Online (Self-Registration)','Assalamu\'alaikum {nama},\r\n\r\nTerimakasih! \r\nTelah mengisi formulir SMPB SMK PGRI BLORA\r\nPendaftaran Anda telah berhasil.\r\n\r\n📋 *Detail Pendaftaran:*\r\nNo. Pendaftaran: {no_pendaftaran}\r\nNama: {nama}\r\nJurusan: {jurusan}\r\n\r\n✅ Kalau sudah yakin dengan SMK PGRI BLORA, segera melakukan daftar ulang ke sekolah.\r\nJadwal Loket Perdaftaran di sekolah buka hari Senin - Sabtu, Jam 07.30 - 13.00 WIB,\r\n\r\nditunggu kedatangannya ya,🙏🙏 \r\n\r\n🔗 Portal: {portal_url}\r\n\r\nTerima kasih telah mendaftar di SMK PGRI BLORA.\r\n\r\nWassalamu\'alaikum','Pesan otomatis untuk pendaftar yang registrasi sendiri via portal online','registration',1,1,'{\"nama\":\"Nama lengkap pendaftar\",\"no_pendaftaran\":\"Nomor pendaftaran\",\"jurusan\":\"Nama jurusan yang dipilih\",\"portal_url\":\"URL portal SPMB\",\"sekolah\":\"Nama sekolah\"}',26,'2026-06-15 06:22:40','2026-05-31 08:40:32','2026-06-15 13:31:06'),(6,'admin_registration','Notifikasi Pendaftaran oleh Panitia (Manual Entry)','Assalamu\'alaikum {nama},\r\n\r\nAnda telah didaftarkan oleh panitia SPMB SMK PGRI BLORA.\r\n\r\n📋 *Detail Pendaftaran:*\r\nNo. Pendaftaran: {no_pendaftaran}\r\nNama: {nama}\r\nJurusan: {jurusan}\r\n\r\n✅ Kalau sudah yakin dengan SMK PGRI BLORA, segera melakukan daftar ulang ke sekolah.\r\nJadwal Loket Perdaftaran di sekolah buka hari Senin - Sabtu, Jam 07.30 - 13.00 WIB,\r\n\r\nditunggu kedatangannya ya,🙏🙏 \r\n\r\n🔗 Portal: {portal_url}\r\n\r\nJika ada pertanyaan, silakan hubungi panitia.\r\n\r\nTerima kasih.\r\n\r\nWassalamu\'alaikum','Pesan otomatis saat petugas/panitia menambahkan pendaftar baru secara manual','registration',1,1,'{\"nama\":\"Nama lengkap pendaftar\",\"no_pendaftaran\":\"Nomor pendaftaran\",\"jurusan\":\"Nama jurusan yang dipilih\",\"portal_url\":\"URL portal SPMB\",\"sekolah\":\"Nama sekolah\"}',0,NULL,'2026-06-15 13:31:06','2026-06-15 14:11:54'),(7,'phone_number_added','Notifikasi Nomor HP Ditambahkan','Assalamu\'alaikum {nama},\r\n\r\nanda telah didaftarkan oleh panitia SPMB SMK PGRI BLORA.\r\n\r\nNomor HP juga telah berhasil ditambahkan ke sistem SPMB SMK PGRI BLORA.\r\n\r\n📋 *Detail Pendaftaran:*\r\nNo. Pendaftaran: {no_pendaftaran}\r\nNama: {nama}\r\nJurusan: {jurusan}\r\nNomor HP: {nomor_hp}\r\n\r\n✅ Anda sekarang dapat menerima notifikasi penting terkait pendaftaran.\r\n✅ Kalau sudah yakin dengan SMK PGRI BLORA, segera melakukan daftar ulang ke sekolah.\r\nJadwal Loket Perdaftaran di sekolah buka hari Senin - Sabtu, Jam 07.30 - 13.00 WIB,\r\n\r\nditunggu kedatangannya ya,🙏🙏 \r\n\r\n🔗 Portal: {portal_url}\r\n\r\nTerima kasih.\r\n\r\nWassalamu\'alaikum','Pesan otomatis saat petugas menambahkan nomor HP siswa via edit data','notification',1,1,'{\"nama\":\"Nama lengkap pendaftar\",\"no_pendaftaran\":\"Nomor pendaftaran\",\"jurusan\":\"Nama jurusan yang dipilih\",\"nomor_hp\":\"Nomor HP yang baru ditambahkan\",\"portal_url\":\"URL portal SPMB\",\"sekolah\":\"Nama sekolah\"}',4,'2026-06-15 14:58:07','2026-06-15 13:31:06','2026-06-15 14:58:07'),(8,'daftar_ulang_verified','Konfirmasi Verifikasi Daftar Ulang','Assalamu\'alaikum {nama},\r\n\r\n✅ *Verifikasi Daftar Ulang Berhasil*\r\n\r\nSelamat! Daftar ulang Anda telah diverifikasi oleh panitia.\r\n\r\n📋 *Detail:*\r\nNo. Pendaftaran: {no_pendaftaran}\r\nNama: {nama}\r\nJurusan: {jurusan}\r\nUkuran Kaos: {ukuran_kaos}\r\n\r\n📝 Langkah selanjutnya:\r\n1. Tunggu informasi selanjutnya dari panitia SPMB untuk masuk ke grub sekolah\r\n2. Santai, duduk manis, dan tenang.😆 \r\n\r\n🔗 Portal: {portal_url}\r\n\r\nSelamat bergabung dengan keluarga besar SMK PGRI BLORA!\r\n\r\nWassalamu\'alaikum','Notifikasi otomatis saat petugas memverifikasi daftar ulang siswa','notification',1,1,'{\"nama\":\"Nama lengkap pendaftar\",\"no_pendaftaran\":\"Nomor pendaftaran\",\"jurusan\":\"Nama jurusan yang dipilih\",\"ukuran_kaos\":\"Ukuran kaos yang dipilih (S\\/M\\/L\\/XL\\/XXL\\/JUMBO)\",\"portal_url\":\"URL portal SPMB\",\"sekolah\":\"Nama sekolah\"}',2,'2026-06-15 14:30:30','2026-06-15 13:59:15','2026-06-15 14:30:30'),(10,'enrollment_reminder','Pengingat Daftar Ulang','Assalamu\'alaikum {nama},\n\n⏰ *Pengingat Daftar Ulang*\n\nAnda telah DITERIMA di {sekolah}, namun belum melakukan daftar ulang.\n\n📋 *Detail:*\nNo. Pendaftaran: {no_pendaftaran}\nNama: {nama}\nJurusan: {jurusan}\n\n⚠️ *Penting:*\nSegera lakukan daftar ulang untuk mengamankan kursi Anda.\n\n📝 *Cara Daftar Ulang:*\n1. Kunjungi portal SPMB\n2. Upload bukti pembayaran\n3. Pilih ukuran seragam\n4. Tunggu verifikasi panitia\n\n🔗 Portal: {portal_url}\n\nJangan sampai terlewat!\n\nWassalamu\'alaikum','Pengingat untuk siswa yang sudah diterima tapi belum daftar ulang','notification',1,0,'{\"nama\":\"Nama lengkap pendaftar\",\"no_pendaftaran\":\"Nomor pendaftaran\",\"jurusan\":\"Nama jurusan yang dipilih\",\"portal_url\":\"URL portal SPMB\",\"sekolah\":\"Nama sekolah\"}',0,NULL,'2026-06-15 13:59:15','2026-06-15 13:59:15'),(11,'orientation_info','Informasi Jadwal Orientasi (MPLS)','Assalamu\'alaikum {nama},\n\n📅 *Informasi Masa Orientasi Siswa Baru*\n\nBerikut jadwal Masa Pengenalan Lingkungan Sekolah (MPLS):\n\n📋 *Peserta:*\nNama: {nama}\nNo. Pendaftaran: {no_pendaftaran}\nJurusan: {jurusan}\n\n📅 *Jadwal MPLS:*\nTanggal: {tanggal_mpls}\nWaktu: {waktu_mpls}\nTempat: {sekolah}\n\n📝 *Yang Perlu Dibawa:*\n1. Kartu peserta (download di portal)\n2. Alat tulis\n3. Seragam (jika sudah diambil)\n\n🔗 Portal: {portal_url}\n\nSampai jumpa!\n\nWassalamu\'alaikum','Informasi jadwal masa orientasi siswa baru (MPLS)','notification',1,0,'{\"nama\":\"Nama lengkap pendaftar\",\"no_pendaftaran\":\"Nomor pendaftaran\",\"jurusan\":\"Nama jurusan yang dipilih\",\"tanggal_mpls\":\"Tanggal MPLS\",\"waktu_mpls\":\"Waktu MPLS\",\"portal_url\":\"URL portal SPMB\",\"sekolah\":\"Nama sekolah\"}',0,NULL,'2026-06-15 13:59:15','2026-06-15 13:59:15');
